SHOW_GRAY_WORK_THUMBNAIL = True
GRAY_THUMBNAIL_MAX_WIDTH = 128
GRAY_THUMBNAIL_MAX_HEIGHT = 180
GRAY_THUMBNAIL_MARGIN_PX = 8

# ``to_ide=True`` remains enabled as a low-cost display-mirror fallback. The
