"""Lightweight CPython/CanMV performance counters for the puzzle pipeline."""

import time



def ticks_ms():
    function = getattr(time, "ticks_ms", None)
    if function is not None:
        return int(function())
    function = getattr(time, "perf_counter", None)
    if function is not None:
        return int(function() * 1000.0)
    return int(time.time() * 1000.0)


def ticks_diff(newer, older):
    function = getattr(time, "ticks_diff", None)
    if function is not None:
        return int(function(newer, older))
    return int(newer - older)


class PerformanceStats:
    """Accumulate named durations and counters without CPython-only features."""

    __slots__ = (
        "enabled",
        "frame_index",
        "frame_started_ms",
        "last_stages",
        "window_stage_ms",
        "window_stage_count",
        "counters",
        "window_frames",
        "boundary_fallback_count",
    )

    def __init__(self, enabled=None):
        if enabled is None:
            enabled = cfg.ENABLE_STAGE_TIMING
        self.enabled = bool(enabled)
        self.frame_index = -1
        self.frame_started_ms = 0
        self.last_stages = {}
        self.window_stage_ms = {}
        self.window_stage_count = {}
        self.counters = {}
        self.window_frames = 0
        self.boundary_fallback_count = 0

    def reset(self):
        enabled = self.enabled
        self.__init__(enabled=enabled)

    def begin_frame(self, frame_index):
        if not self.enabled:
            return 0
        self.frame_index = int(frame_index)
        self.frame_started_ms = ticks_ms()
        self.last_stages = {}
        return self.frame_started_ms

    def mark(self):
        return ticks_ms() if self.enabled else 0

    def add_stage(self, name, started_ms=None, elapsed_ms=None):
        if not self.enabled:
            return 0
        if elapsed_ms is None:
            elapsed_ms = ticks_diff(ticks_ms(), started_ms)
        elapsed_ms = max(0, int(elapsed_ms))
        self.last_stages[name] = (
            self.last_stages.get(name, 0) + elapsed_ms
        )
        self.window_stage_ms[name] = (
            self.window_stage_ms.get(name, 0) + elapsed_ms
        )
        self.window_stage_count[name] = (
            self.window_stage_count.get(name, 0) + 1
        )
        return elapsed_ms

    def increment(self, name, amount=1):
        if not self.enabled:
            return
        self.counters[name] = self.counters.get(name, 0) + int(amount)
        if name == "boundary_fallback_count":
            self.boundary_fallback_count += int(amount)

    def end_frame(self):
        if not self.enabled:
            return 0
        total = ticks_diff(ticks_ms(), self.frame_started_ms)
        self.add_stage("total_frame_ms", elapsed_ms=total)
        self.window_frames += 1
        return total

    def report_due(self, frame_index=None):
        if not self.enabled:
            return False
        if frame_index is None:
            frame_index = self.frame_index
        interval = max(1, int(cfg.TIMING_REPORT_INTERVAL_FRAMES))
        return self.window_frames > 0 and int(frame_index) % interval == 0

    def last_snapshot(self):
        return dict(self.last_stages)

    def window_snapshot(self, reset=False):
        averages = {}
        for name, total in self.window_stage_ms.items():
            averages[name] = float(total) / max(
                1, self.window_stage_count.get(name, 1)
            )
        result = {
            "frames": self.window_frames,
            "averages_ms": averages,
            "last_ms": dict(self.last_stages),
            "counters": dict(self.counters),
        }
        if reset:
            self.window_stage_ms = {}
            self.window_stage_count = {}
            self.counters = {}
            self.window_frames = 0
        return result

    def format_report(self, frame_index=None):
        if frame_index is None:
            frame_index = self.frame_index
        snapshot = self.window_snapshot(reset=False)
        averages = snapshot["averages_ms"]
        ordered = (
            "capture_ms",
            "a4_detect_ms",
            "rectify_ms",
            "segment_ms",
            "blob_ms",
            "contour_ms",
            "polygon_fit_ms",
            "candidate_graph_ms",
            "plan_ms",
            "coverage_scan_ms",
            "render_ms",
            "display_ms",
            "total_frame_ms",
        )
        fields = [
            "{}={:.1f}".format(name[:-3], averages[name])
            for name in ordered
            if name in averages
        ]
        return "[PERF] frame={} frames={} {}".format(
            int(frame_index),
            snapshot["frames"],
            " ".join(fields),
        )


PERF_STATS = PerformanceStats()

"""Pure-Python geometry, tracking, and rectangle assembly for the A4 puzzle.

This module deliberately avoids OpenCV, NumPy, dataclasses, and CPython-only
features so the same planner runs unchanged on CanMV K230 MicroPython.
Coordinates passed to this module are always millimetres.
"""

import math
import os



EPS = 1e-7
GEOMETRY_COUNTERS = {
    "polygon_intersection_calls": 0,
    "aabb_reject_count": 0,
}
PLAN_DEBUG_STATE = None


def reset_geometry_counters():
    GEOMETRY_COUNTERS["polygon_intersection_calls"] = 0
    GEOMETRY_COUNTERS["aabb_reject_count"] = 0


def geometry_counters_snapshot():
    return dict(GEOMETRY_COUNTERS)


def begin_plan_debug(planner, piece_count):
    """Start one low-frequency planner heartbeat session."""
    global PLAN_DEBUG_STATE
    if not getattr(cfg, "ENABLE_PLAN_DEBUG", False):
        PLAN_DEBUG_STATE = None
        return
    reset_geometry_counters()
    now = ticks_ms()
    PLAN_DEBUG_STATE = {
        "planner": str(planner),
        "stage": "dispatch",
        "started_ms": now,
        "last_report_ms": now,
        "piece_count": int(piece_count),
        "depth": 0,
        "states": 0,
        "expanded": 0,
        "nodes": 0,
        "work": 0,
        "best_score": None,
    }


def update_plan_debug(
    stage=None,
    depth=None,
    states=None,
    expanded=None,
    nodes=None,
    best_score=None,
):
    """Update heartbeat fields without reading the clock or printing."""
    state = PLAN_DEBUG_STATE
    if state is None:
        return
    if stage is not None:
        state["stage"] = str(stage)
    if depth is not None:
        state["depth"] = int(depth)
    if states is not None:
        state["states"] = int(states)
    if expanded is not None:
        state["expanded"] = int(expanded)
    if nodes is not None:
        state["nodes"] = int(nodes)
    if best_score is not None:
        state["best_score"] = float(best_score)


def plan_debug_heartbeat(force=False):
    """Print progress only when the configured wall-clock interval elapsed."""
    state = PLAN_DEBUG_STATE
    if state is None:
        return False
    now = ticks_ms()
    elapsed_since_report = ticks_diff(
        now, state["last_report_ms"]
    )
    interval_ms = max(
        250,
        int(getattr(cfg, "PLAN_DEBUG_INTERVAL_MS", 2000)),
    )
    if not force and elapsed_since_report < interval_ms:
        return False
    elapsed_ms = max(
        0, ticks_diff(now, state["started_ms"])
    )
    best_score = state["best_score"]
    best_text = (
        "na"
        if best_score is None
        else "{:.4f}".format(best_score)
    )
    print(
        "PLAN_DEBUG,planner={},stage={},elapsed_ms={},pieces={},"
        "depth={},states={},expanded={},nodes={},work={},"
        "best_score={},intersections={},aabb_rejects={}".format(
            state["planner"],
            state["stage"],
            elapsed_ms,
            state["piece_count"],
            state["depth"],
            state["states"],
            state["expanded"],
            state["nodes"],
            state["work"],
            best_text,
            GEOMETRY_COUNTERS["polygon_intersection_calls"],
            GEOMETRY_COUNTERS["aabb_reject_count"],
        )
    )
    state["last_report_ms"] = now
    return True


def end_plan_debug():
    """End the active heartbeat session without adding another log line."""
    global PLAN_DEBUG_STATE
    PLAN_DEBUG_STATE = None


def _plan_debug_work(amount=1):
    state = PLAN_DEBUG_STATE
    if state is not None:
        state["work"] += int(amount)


def _plan_debug_checkpoint(interval=32):
    """Poll time/IDE only once per small batch of expensive helper calls."""
    state = PLAN_DEBUG_STATE
    if state is None:
        return
    state["work"] += 1
    if state["work"] % max(1, int(interval)) != 0:
        return
    exitpoint = getattr(os, "exitpoint", None)
    if exitpoint is not None:
        exitpoint()
    plan_debug_heartbeat()


def _geometry_exitpoint(counter, interval=32):
    """Keep long planner searches interruptible from CanMV IDE."""
    if counter % interval != 0:
        return
    _plan_debug_work(interval)
    exitpoint = getattr(os, "exitpoint", None)
    if exitpoint is not None:
        exitpoint()
    plan_debug_heartbeat()


