                cfg.A4_DETECT_WIDTH,
                cfg.A4_DETECT_HEIGHT,
                cfg.REALTIME_PIECE_WORK_WIDTH,
                cfg.REALTIME_PIECE_WORK_HEIGHT,
                cfg.A4_DETECT_INTERVAL_ACQUIRE,
                cfg.PIECE_DETECT_EVERY_N_FRAMES,
